<?php
if (!defined('ABSPATH')) { exit; }
global $wpdb;
$products = $wpdb->get_results("SELECT ID,post_status FROM {$wpdb->posts} WHERE post_type='product' ORDER BY ID", ARRAY_A);
$catalog = array(); $priced=0; $unpriced=0;
foreach($products as $row){ $p=wc_get_product($row['ID']); if(!$p){continue;} $raw=$p->get_data(); $catalog[]=array($p->get_id(),$row['post_status'],$raw['regular_price'],$raw['sale_price'],$raw['stock_status']); if($row['post_status']==='publish'){ if($raw['price']===''){$unpriced++;}else{$priced++;} } }
$orders=wc_get_orders(array('limit'=>-1,'return'=>'objects','orderby'=>'ID','order'=>'ASC'));
$order_state=array();foreach($orders as $o){$order_state[]=array($o->get_id(),$o->get_status(),$o->get_currency(),$o->get_total(),$o->get_customer_id(),$o->get_transaction_id());}
$methods=array();foreach(WC()->payment_gateways()->payment_gateways() as $id=>$g){if(strpos($id,'instapass_')!==0){continue;}$methods[$id]=array('enabled'=>$g->enabled,'instructions_configured'=>!empty($g->instructions),'available'=>$g->is_available(),'currencies'=>$g->get_option('instapass_currencies',function_exists('instapass_cc_gateway_currencies')?array(instapass_cc_gateway_currencies($id)[0]):array()));}
$coupons=get_posts(array('post_type'=>'shop_coupon','post_status'=>'publish','numberposts'=>-1));$promo=array();foreach($coupons as $p){$c=new WC_Coupon($p->ID);$promo[]=array('code'=>$c->get_code(),'type'=>$c->get_discount_type(),'amount'=>$c->get_amount(),'usage_limit'=>$c->get_usage_limit(),'usage_limit_per_user'=>$c->get_usage_limit_per_user());}
$pages=get_posts(array('post_type'=>'page','post_status'=>'publish','numberposts'=>-1));$tracking=array();foreach($pages as $p){if(stripos($p->post_name,'track')!==false || has_shortcode($p->post_content,'woocommerce_order_tracking') || has_shortcode($p->post_content,'instapass_order_tracking')){$tracking[]=array('id'=>$p->ID,'slug'=>$p->post_name);}}
echo wp_json_encode(array('theme_path'=>get_template_directory(),'options'=>array('guest'=>get_option('woocommerce_enable_guest_checkout'),'checkout_registration'=>get_option('woocommerce_enable_signup_and_login_from_checkout'),'myaccount_registration'=>get_option('woocommerce_enable_myaccount_registration'),'coupons'=>get_option('woocommerce_enable_coupons'),'currency'=>get_option('woocommerce_currency'),'admin_email_is_owner'=>strtolower(get_option('admin_email'))==='instapass0408@gmail.com'),'products'=>array('published_priced'=>$priced,'published_unpriced'=>$unpriced,'hash'=>hash('sha256',wp_json_encode($catalog))),'orders'=>array('count'=>count($order_state),'hash'=>hash('sha256',wp_json_encode($order_state))),'gateways'=>$methods,'coupons'=>$promo,'tracking_pages'=>$tracking),JSON_PRETTY_PRINT);
